using IracingLiveCoach.Core.Telemetry;
using IracingLiveCoach.OverlayHost.Theme;
using Vortice.Win32; using Vortice.Win32.Graphics.Direct2D; using Vortice.Win32.Graphics.DirectWrite; using Vortice.Win32.Numerics; using static Vortice.Win32.Apis;
namespace IracingLiveCoach.OverlayHost.Widgets;
public sealed unsafe class StartHelperWidget:IDisposable
{private readonly TelemetryReader _t=new();private readonly object _g=new();private RaceStartStatus? _s;private ComPtr<IDWriteTextFormat> _f;private ComPtr<ID2D1SolidColorBrush> _b;
public StartHelperWidget(ID2D1DeviceContext*d,IDWriteFactory*w){_f=w->CreateTextFormat("Barlow Semi Condensed",13f,fontWeight:FontWeight.SemiBold,localeName:"en-us");ThrowIfFailed(_f.Get()->SetParagraphAlignment(ParagraphAlignment.Center));var c=PaletteTokens.TextPrimary;ThrowIfFailed(d->CreateSolidColorBrush(&c,null,_b.GetAddressOf()));_t.RaceStartUpdated+=x=>{lock(_g)_s=x;};_t.Start();}
public void Draw(ID2D1DeviceContext*d,float x,float y,float w=280){RaceStartStatus?s;lock(_g)s=_s;if(s?.ShouldShow!=true)return;DrawBar(d,"CLUTCH",s.ClutchPct,x,y,w);DrawBar(d,"THROTTLE",s.ThrottlePct,x,y+25,w);}private void DrawBar(ID2D1DeviceContext*d,string label,double value,float x,float y,float w){var bg=PaletteTokens.OverlayBackground;_b.Get()->SetColor(&bg);var r=new RectF(x,y,x+w,y+21);d->FillRectangle(&r,(ID2D1Brush*)_b.Get());var fill=PaletteTokens.StartHelperInRange;_b.Get()->SetColor(&fill);var f=new RectF(x+90,y+5,x+90+(w-100)*(float)Math.Clamp(value/100,0,1),y+16);d->FillRectangle(&f,(ID2D1Brush*)_b.Get());var t=$"{label} {value:0}%";var tr=new RectF(x+5,y,x+w-5,y+21);var text=PaletteTokens.TextPrimary;_b.Get()->SetColor(&text);fixed(char*p=t)d->DrawText(p,(uint)t.Length,_f.Get(),&tr,(ID2D1Brush*)_b.Get(),DrawTextOptions.None,MeasuringMode.Natural);}public void Dispose(){_t.Dispose();_f.Dispose();_b.Dispose();}}
